<?php require_once __DIR__.'/../app/bootstrap.php';$username=trim($_GET['u']??'');$q=db()->prepare('SELECT u.id,u.username,u.created_at,p.* FROM users u JOIN profiles p ON p.user_id=u.id WHERE u.username=? AND u.status=\'active\'');$q->execute([$username]);$seller=$q->fetch();if(!$seller){http_response_code(404);exit('Vendedor no encontrado.');}$pro=profile_pro((int)$seller['id']);$pr=db()->prepare("SELECT products.*,categories.name category FROM products JOIN categories ON categories.id=products.category_id WHERE products.user_id=? AND products.status='published' ORDER BY products.created_at DESC");$pr->execute([$seller['id']]);$products=$pr->fetchAll();$pageTitle=$seller['display_name'].' · Vendedor';$pageDescription=mb_strimwidth(strip_tags((string)($seller['bio']?:$seller['business_local']?:'Perfil comercial en ComercioSocial')),0,300,'…');$pageCanonical=url('profile.php?u='.urlencode($seller['username']));$pageImage=$seller['cover']?:$seller['avatar']?:'assets/cover.svg';require __DIR__.'/../partials/header.php';?><link rel="stylesheet" href="<?=url('assets/css/feedback.css')?>">
